def _admin_ids_env():
    raw = str(os.getenv("ROM_ADMIN_USER_IDS", "")).strip()
    return frozenset(int(part.strip()) for part in raw.split(",") if part.strip())

def _validated_external_https_url(value, allowed_hosts):
    value = str(value or "").strip()
    if not value or len(value) > 2048:
        return None
    try:
        parsed = _urlsplit(value)
    except Exception:
        return None
    host = str(parsed.hostname or "").casefold()
    allowed = {str(item).casefold() for item in allowed_hosts}
    if (
        parsed.scheme.casefold() != "https"
        or not host
        or host not in allowed
        or parsed.username
        or parsed.password
        or parsed.fragment
    ):
        return None
    return value

def calculate_total_defense(item_defense, primary_stat):
    """Combine active item defense with the symmetric primary-stat layer."""
    return max(0.0, float(item_defense or 0)) + calculate_stat_defense(primary_stat)

