def build_story_quest_callback(action: str, value: str = "") -> str:
    """Build a compact namespaced callback accepted by the future handler."""
    action_key = str(action or "").strip().lower()
    value_key = str(value or "").strip()
    if not action_key or ":" in action_key or ":" in value_key:
        raise StoryQuestUiError("invalid story quest callback component")
    payload = f"{STORY_QUEST_CALLBACK_PREFIX}{action_key}"
    if value_key:
        payload += f":{value_key}"
    if len(payload.encode("utf-8")) > 64:
        raise StoryQuestUiError("story quest callback exceeds Telegram limit")
    return payload

def parse_story_quest_callback(payload: str) -> StoryQuestCallback:
    """Fail closed for callbacks outside the canonical namespace."""
    raw = str(payload or "")
    if not raw.startswith(STORY_QUEST_CALLBACK_PREFIX):
        raise StoryQuestUiError("foreign callback namespace")
    parts = raw[len(STORY_QUEST_CALLBACK_PREFIX):].split(":")
    if not parts or not parts[0] or len(parts) > 2:
        raise StoryQuestUiError("invalid story quest callback")
    return StoryQuestCallback(parts[0], parts[1] if len(parts) == 2 else "")

def render_story_quest_detail(item: Mapping, *, page: int = 0) -> dict:
    """Render one quest using only canonical lifecycle snapshot fields."""
    quest_id = str(item.get("quest_id") or "").strip()
    if not quest_id:
        raise StoryQuestUiError("quest_id is required")
    status = str(item.get("status") or "LOCKED")
    progress = int(item.get("quest_item_quantity", 0) or item.get("progress", 0))
    target = int(item.get("target_quantity", 1))
    lines = [
        f"📜 {int(item.get('number', 0))}. {str(item.get('title') or 'Без назви')}",
        "",
        _status_label(status),
        f"Прогрес: {min(progress, target)}/{target}",
    ]
    return {
        "text": "\n".join(lines),
        "keyboard": build_story_quest_detail_keyboard(
            quest_id=quest_id, status=status, page=page,
        ),
    }

def _inline_markup(rows):
    """Convert pure descriptors to telebot markup only at the delivery boundary."""
    from telebot import types

    markup = types.InlineKeyboardMarkup()
    for row in rows:
        markup.row(*[
            types.InlineKeyboardButton(
                text=button["text"], callback_data=button["callback_data"]
            )
            for button in row
        ])
    return markup

def _should_show_story_quest_progress(status: str, quest) -> bool:
    """Return whether the production journal must render objective progress.

    Single-target BOSS objectives still have meaningful 0/1 and 1/1 states:
    1/1 remains ACTIVE until the player reports victory to the completion NPC.
    """
    return str(status) == "ACTIVE" and (
        int(quest.target_quantity) > 1
        or quest.quest_type in (QuestType.QUEST_ITEM, QuestType.BOSS)
    )

def resolve_story_quest_journal_navigation(quest, status: str, progress: int):
    """Resolve a journal route from canonical lifecycle state and ownership.

    Static objective/next-step hints describe content, not a reliable live
    route. Completion ownership comes from `turn_in_npc_id or giver_npc_id`,
    which also corrects cross-NPC handoffs such as quest 23 without rewriting
    quest definitions. Terminal states intentionally expose no active route.
    """
    from data.story_quest_npcs import resolve_story_quest_navigation

    state = str(status or "LOCKED").upper()
    if state in {"LOCKED", "COMPLETED", "SKIPPED"}:
        return None

    def npc_route(npc_id):
        navigation = resolve_story_quest_navigation(str(npc_id))
        return str(navigation["route_text"])

    if state == "AVAILABLE":
        return "🧭 Де прийняти:", npc_route(quest.giver_npc_id)
    if state != "ACTIVE":
        return None

    target = max(1, int(quest.target_quantity))
    current = max(0, int(progress))
    completion_npc_id = quest.turn_in_npc_id or quest.giver_npc_id
    quest_type = quest.quest_type

    if quest_type is QuestType.TALK:
        return "🧭 З ким поговорити:", npc_route(completion_npc_id)
    if quest_type is QuestType.TURN_IN:
        return "🧭 Кому передати:", npc_route(completion_npc_id)
    if current >= target:
        label = "🧭 Кому передати:" if quest_type is QuestType.QUEST_ITEM else "🧭 Кому доповісти:"
        return label, npc_route(completion_npc_id)

    location_name = resolve_story_quest_location_name(quest.location_id)
    if quest_type is QuestType.QUEST_ITEM:
        return "🧭 Де шукати:", f"🌿 {location_name} → 🔎 Полювання"
    if quest_type is QuestType.BOSS:
        return "🧭 Як викликати:", f"🌿 {location_name} → 👀 Роззирнутися"
    if quest_type is QuestType.KILL_REGION:
        return "🧭 Де виконувати:", f"🌿 {location_name} → 🔎 Полювання"
    return "🧭 Де виконувати:", f"🌿 {location_name}"

