def migrate(conn):
    columns={str(row[1]) for row in conn.execute("PRAGMA table_info(users)").fetchall()}
    if "registered_at" not in columns:
        conn.execute("ALTER TABLE users ADD COLUMN registered_at TEXT DEFAULT ''")
