    uid = int(user_id)
    if is_user_travelling(uid):
        return "travel"
    node = str(get_current_location(uid) or CITY_NODE)
    if node == CITY_NODE:
        return "city"
    profile = WORLD_NODES.get(node)
    if profile and profile.get("kind") == "location":
