        bot.user_data[int(uid)]=mob; restored.append(int(uid))
    return {'escaped_user_ids':[x['user_id'] for x in expired], 'restored_user_ids':restored, 'expired_encounter_ids':sorted(expired_ids)}

def get_pve_skill_action_state(user_id, mob, skill):
    """Return current PvE skill UI state without mutating DB or combat state."""
    del user_id
    mob = mob or {}
    skill = skill or {}
    name = str(skill.get("name") or skill.get("key") or "Навичка")
    key = str(skill.get("key") or "")

    cooldowns = mob.get("skill_cooldowns") or {}
    cooldown = max(0, int(cooldowns.get(key, 0) or 0))
    if cooldown > 0:
        return _state(
            skill, False, "cooldown",
            f"⏳ {name} · ще {_turns_uk(cooldown)}",
            f"⏳ {name} ще перезаряджається. Залишилось: {_turns_uk(cooldown)}.",
            remaining=cooldown,
        )

    player_stunned = max(0, int(mob.get("player_stunned_turns", 0) or 0))
    player_effects = mob.get("player_effects") or {}
    controlled = player_stunned > 0 or any(
        str(effect.get("type") or "").lower() in {"stun", "silence", "control"}
        and int(effect.get("turns", 0) or 0) > 0
        for effect in player_effects.values()
        if isinstance(effect, dict)
    )
    if controlled:
        return _state(
            skill, False, "control_state",
            f"🔒 {name} · зараз недоступна",
            f"🔒 {name} зараз недоступна через ефект контролю.",
        )

    cost_type = str(skill.get("cost_type") or "")
    cost = get_pve_effective_skill_cost(mob, skill)

    if cost_type == "rage":
        current = max(0, int(mob.get("player_rage", 0) or 0))
        if current < cost:
            return _state(skill, False, "not_enough_rage",
                          f"🔒 {name} · потрібно {cost} Люті",
                          f"🔴 Недостатньо Люті для {name}. Потрібно: {cost}, доступно: {current}.",
                          required=cost, available_amount=current)

    elif cost_type == "rage_all_min":
        required = max(0, int(skill.get("min_cost", 30) or 30))
        current = max(0, int(mob.get("player_rage", 0) or 0))
        if current < required:
            return _state(skill, False, "not_enough_rage",
                          f"🔒 {name} · потрібно {required} Люті",
                          f"🔴 Недостатньо Люті для {name}. Потрібно мінімум: {required}, доступно: {current}.",
                          required=required, available_amount=current)

    elif cost_type in {"combat_energy", "combat_energy_combo"}:
        current = max(0, int(mob.get("player_combat_energy", 0) or 0))
        maximum = max(0, int(mob.get("player_max_combat_energy", 100) or 100))
        projected = min(maximum, current + 20)
        if projected < cost:
            return _state(skill, False, "not_enough_combat_energy",
                          f"🔒 {name} · потрібно {cost} Енергії",
                          f"🟡 Недостатньо Енергії для {name}. Потрібно: {cost}, на початку ходу буде доступно: {projected}.",
                          required=cost, available_amount=projected)
        if cost_type == "combat_energy_combo":
            required_combo = max(1, int(skill.get("min_combo", 1) or 1))
            combo = max(0, int(mob.get("player_combo_points", 0) or 0))
            if combo < required_combo:
                return _state(skill, False, "not_enough_combo",
                              f"🔒 {name} · потрібно {required_combo} комбо",
                              f"⚔️ Недостатньо комбо для {name}. Потрібно: {required_combo}, доступно: {combo}.",
                              required=required_combo, available_amount=combo)

    elif cost_type == "mana":
        current = max(0, int(mob.get("player_mp", 0) or 0))
        maximum = max(0, int(mob.get("player_max_mp", 0) or 0))
        if skill.get("key") == "mage_arcane_flow" and maximum > 0 and current >= maximum:
            return _state(skill, False, "mana_already_full",
                          f"🔒 {name} · Мана вже повна",
                          "🔵 Мана вже повна.",
                          required=cost, available_amount=current, effective_cost=cost)
        if current < cost:
            return _state(skill, False, "not_enough_mana",
                          f"🔒 {name} · потрібно {cost} Мани",
                          f"🔵 Недостатньо Мани для {name}. Потрібно: {cost}, доступно: {current}.",
                          required=cost, available_amount=current, effective_cost=cost)

    return _state(skill, True, "ok", f"✨ {name}", "", effective_cost=cost)

def _catalog(params):
    source = load_production_pvp_skill_catalog()
    catalog = {class_key: tuple(dict(skill) for skill in skills) for class_key, skills in source.items()}
    for class_key, skills in catalog.items():
        for skill in skills:
            key = str(skill.get("key") or "")
            if class_key == "warrior" and float(skill.get("damage_multiplier") or 0) > 0:
                skill["damage_multiplier"] = float(skill["damage_multiplier"]) * params["warrior_skill"]
            elif class_key == "knight" and float(skill.get("damage_multiplier") or 0) > 0:
                skill["damage_multiplier"] = float(skill["damage_multiplier"]) * params["knight_skill"]
            elif class_key == "scout" and float(skill.get("damage_multiplier") or 0) > 0:
                skill["damage_multiplier"] = float(skill["damage_multiplier"]) * params["scout_skill"]
            elif class_key == "rogue" and float(skill.get("damage_multiplier") or 0) > 0:
                skill["damage_multiplier"] = float(skill["damage_multiplier"]) * params["rogue_skill"]
            elif class_key == "mage" and float(skill.get("damage_multiplier") or 0) > 0:
                skill["damage_multiplier"] = float(skill["damage_multiplier"]) * params["mage_skill"]
            elif class_key == "priest" and key == "priest_holy_ray":
                skill["damage_multiplier"] = float(skill["damage_multiplier"]) * params["priest_damage"]
            if key == "knight_shield_bash":
                skill["stun_chance"] = params["shield_bash_stun"]
    return catalog

def _actor(class_key, user_id, params):
    actor = build_real_actor(class_key, user_id)
    reference = PRODUCTION_REFERENCE[class_key]
    if class_key == "warrior":
        actor.physical_defense *= params["warrior_pdef"]
    elif class_key == "scout":
        actor.physical_attack = max(float(reference["str"]), float(reference["dex"]) * params["scout_dex_patk"])
    elif class_key == "rogue":
        actor.physical_attack = max(float(reference["str"]), float(reference["dex"]) * params["rogue_dex_patk"])
    elif class_key == "mage":
        actor.magical_attack *= params["mage_matk"]
    elif class_key == "knight":
        actor.physical_defense *= params["knight_pdef"]
    elif class_key == "priest":
        actor.magical_defense *= params["priest_mdef"]
    return actor

def _scale_priest_hot(actor, params, seen_hot):
    if actor.class_key != "priest" or "hot" not in actor.effects:
        return
    hot = actor.effects["hot"]
    marker = (actor.user_id, int(hot.get("source_id", actor.user_id)), int(hot.get("duration", 0)), float(hot.get("power", 0)))
    if marker in seen_hot:
        return
    original = float(hot.get("power", 0) or 0)
    hot["power"] = max(1, round(original * params["priest_hot"]))
    seen_hot.add((actor.user_id, int(hot.get("source_id", actor.user_id)), int(hot.get("duration", 0)), float(hot.get("power", 0))))

def _cap_winner(actor_a, actor_b):
    left = actor_a.hp / max(1, actor_a.max_hp)
    right = actor_b.hp / max(1, actor_b.max_hp)
    if abs(left - right) < 1e-12:
        return None
    return actor_a.user_id if left > right else actor_b.user_id

def _random_candidate(rng):
    candidate = {}
    for name, (low, high, neutral, _) in PARAMETERS.items():
        if rng.random() < 0.65:
            candidate[name] = _clamp(name, rng.gauss(neutral, (high - low) / 6))
        else:
            candidate[name] = _clamp(name, rng.uniform(low, high))
    return candidate

