def _participant_display_name(participant: Mapping[str, Any]) -> str:
    snapshot = participant.get("snapshot") if isinstance(participant.get("snapshot"), Mapping) else {}
    name = str(participant.get("character_name") or snapshot.get("character_name") or "").strip()
    if not name:
        try:
            from db import get_character_name
            name = str(get_character_name(int(participant.get("user_id") or 0)) or "").strip()
        except Exception:
            name = ""
    return name or f"Гравець #{int(participant.get('user_id') or 0)}"

def load_production_pvp_skill_catalog() -> dict[str, tuple[dict[str, Any], ...]]:
    """Load the one canonical PvE catalog without importing Telegram handlers."""
    path = _ROOT / "handlers" / "combat.py"
    tree = ast.parse(path.read_text(encoding="utf-8"), filename=str(path))
    assignments = []
    for node in ast.walk(tree):
        if isinstance(node, ast.Assign) and any(isinstance(t, ast.Name) and t.id == "CLASS_SKILLS_V1" for t in node.targets):
            assignments.append(node.value)
        elif isinstance(node, ast.AnnAssign) and isinstance(node.target, ast.Name) and node.target.id == "CLASS_SKILLS_V1":
            assignments.append(node.value)
    if len(assignments) != 1:
        raise PvpSkillCatalogError(f"CLASS_SKILLS_V1 assignments={len(assignments)}")
    catalog = ast.literal_eval(assignments[0])
    if not isinstance(catalog, dict):
        raise PvpSkillCatalogError("CLASS_SKILLS_V1 is not a dict")
    normalized = {str(cls): tuple(dict(skill) for skill in skills) for cls, skills in catalog.items()}
    if set(normalized) != {"warrior", "knight", "scout", "rogue", "mage", "priest"}:
        raise PvpSkillCatalogError("production class set changed")
    if sum(len(skills) for skills in normalized.values()) != 18:
        raise PvpSkillCatalogError("production skill count is not 18")
    return normalized

def _normalized_participant(user_id: int, side: str, snapshot: Mapping[str, Any], now: str) -> tuple[Any, ...]:
    class_key = str(snapshot.get("class_key") or snapshot.get("character_class") or "").strip().lower()
    if not class_key:
        raise ValueError("participant class_key is required")
    max_hp = max(1, int(snapshot.get("max_hp") or 1))
    max_mp = max(0, int(snapshot.get("max_mp") or 0))
    resource_type = str(snapshot.get("resource_type") or "rage")
    resource_value = 100 if resource_type in {"combat_energy", "combat_energy_combo"} else 0
    if resource_type == "mana":
        resource_value = max_mp
    return (
        int(user_id), side, class_key, max_hp, max_hp, max_mp, max_mp,
        resource_type, resource_value, 0, 0, 0, "{}", "{}", _json(dict(snapshot)), now, now,
    )

