def _items_from_payload(payload: Mapping[str, Any]):
    candidates = [
        payload.get("final_inventory"),
        payload.get("inventory"),
        _mapping(payload.get("state")).get("inventory"),
        _mapping(payload.get("final_state")).get("inventory"),
    ]
    for candidate in candidates:
        if isinstance(candidate, list):
            return candidate
        if isinstance(candidate, Mapping):
            items = candidate.get("items")
            if isinstance(items, list):
                return items
    return []

def _explicit_unit_sell_value(item: Mapping[str, Any]):
    for key in ("sell_value", "sell_price", "vendor_value", "liquidation_value"):
        if item.get(key) is not None:
            return max(0.0, _number(item.get(key)))
    return None

def build_execution_plan(config: AnalysisConfig, include_walls=True, include_inventory=None):
    config = config.validate()
    include_inventory = config.compare_inventory if include_inventory is None else bool(include_inventory)
    plan = set()

    def add_level(target_level, capacity):
        for character_class in config.classes:
            for profile in config.profiles:
                for seed in config.seeds:
                    plan.add(
                        ScenarioSpec(
                            character_class,
                            profile,
                            int(seed),
                            int(target_level),
                            int(capacity),
                            int(config.max_days),
                        )
                    )

    add_level(config.target_level, config.inventory_capacity)
    if include_walls:
        for target_level in range(2, config.target_level + 1):
            add_level(target_level, config.inventory_capacity)
    if include_inventory:
        add_level(config.target_level, 40)
        add_level(config.target_level, 60)
    return tuple(sorted(plan))

def build_balance_report(config, payloads, execution, include_inventory=None):
    include_inventory = config.compare_inventory if include_inventory is None else bool(include_inventory)
    groups = {}
    for character_class in config.classes:
        groups[character_class] = {}
        for profile in config.profiles:
            specs = [
                ScenarioSpec(character_class, profile, int(seed), config.target_level, config.inventory_capacity, config.max_days)
                for seed in config.seeds
            ]
            groups[character_class][profile] = aggregate_group([payloads[spec] for spec in specs])
    inventory_comparison = None
    if include_inventory:
        inventory_comparison = {
            str(capacity): aggregate_group(_rows_for(payloads, config, config.target_level, capacity))
            for capacity in (40, 60)
        }
    return {
        "schema": "rom.simulation.pve_balance.v1",
        "version": "13.7.2",
        "config": asdict(config),
        "config_fingerprint": config.fingerprint(),
        "run_count": len(config.classes) * len(config.profiles) * len(config.seeds),
        "cache_hits": execution["cache_hits"],
        "execution": execution,
        "groups": groups,
        "inventory_comparison": inventory_comparison,
        "database_writes": 0,
    }

def validate(self):
        if not 2 <= int(self.target_level) <= 10:
            raise ValueError("target_level must be 2..10 for current production content")
        if not self.classes or any(value not in CLASSES for value in self.classes):
            raise ValueError("invalid classes")
        if not self.profiles or any(value not in PROFILES for value in self.profiles):
            raise ValueError("invalid profiles")
        if not self.seeds:
            raise ValueError("at least one seed is required")
        if self.inventory_capacity not in (40, 60):
            raise ValueError("inventory_capacity must be 40 or 60")
        return self

def key_for(spec: ScenarioSpec):
        value = (
            f"{spec.character_class}|{spec.profile}|{spec.seed}|"
            f"{spec.target_level}|{spec.inventory_capacity}|{spec.max_days}"
        )
        return hashlib.sha256(value.encode()).hexdigest()

def choose_potion(self, hp: int, max_hp: int, mp: int, max_mp: int, mana_class: bool, hp_potions: Sequence[Dict[str, Any]], mp_potions: Sequence[Dict[str, Any]]) -> Optional[BehaviorDecision]:
        if max_hp > 0 and hp / max_hp < self.hp_potion_threshold and hp_potions:
            missing = max_hp - hp
            potion = min(hp_potions, key=lambda item: (max(0, int(item.get("restore", 0)) - missing), int(item.get("restore", 0))))
            return BehaviorDecision("use_hp_potion", "hp_below_40_percent", dict(potion))
        if mana_class and max_mp > 0 and mp / max_mp < self.mp_potion_threshold and mp_potions:
            missing = max_mp - mp
            potion = min(mp_potions, key=lambda item: (max(0, int(item.get("restore", 0)) - missing), int(item.get("restore", 0))))
            return BehaviorDecision("use_mp_potion", "mp_below_25_percent", dict(potion))
        return None

def maintenance(self, durability_values: Iterable[int], free_slots: int) -> Optional[BehaviorDecision]:
        values = list(durability_values)
        if values and min(values) <= self.repair_threshold:
            return BehaviorDecision("visit_city", "equipped_durability_at_or_below_15", {"min_durability": min(values)})
        if free_slots <= self.reserve_slots:
            return BehaviorDecision("visit_city", "inventory_reserve_reached", {"free_slots": free_slots})
        return None

def select_mob(self, player_level: int, mobs: Sequence[Dict[str, Any]], contract_target: str = "") -> Optional[Dict[str, Any]]:
        allowed = [mob for mob in mobs if abs(int(mob.get("level", 1)) - int(player_level)) <= 1]
        if contract_target:
            target = next((mob for mob in allowed if str(mob.get("name", "")) == contract_target), None)
            if target:
                return target
        if not allowed:
            return None
        # Balanced policy prefers equal level, then lower risk, then +1.
        return min(allowed, key=lambda mob: (abs(int(mob.get("level", 1)) - player_level), int(mob.get("level", 1)) > player_level, str(mob.get("name", ""))))

def descriptor(name: str) -> CanonicalRuleDescriptor:
    for item in RULES:
        if item.name == name:
            return item
    raise CanonicalRuleError(f"unknown canonical rule: {name}")

def call_rule(name: str, *args: Any, rng: Optional[SimulationRng] = None, **kwargs: Any) -> Any:
    item = descriptor(name)
    module, function = _resolve(item)
    safe_args = deepcopy(args)
    safe_kwargs = deepcopy(kwargs)
    if item.rng_injected:
        if rng is None:
            raise CanonicalRuleError(f"rule {name} requires SimulationRng")
        with inject_module_rng(module, rng):
            return function(*safe_args, **safe_kwargs)
    if rng is not None:
        raise CanonicalRuleError(f"rule {name} does not accept RNG")
    return function(*safe_args, **safe_kwargs)

def rule_manifest() -> List[Dict[str, Any]]:
    result = []
    for item in RULES:
        module, function = _resolve(item)
        result.append({
            "name": item.name,
            "module": item.module,
            "function": item.function,
            "deterministic": item.deterministic,
            "rng_injected": item.rng_injected,
            "callable": callable(function),
        })
    return result

