def required_new_slots(self,a):
        left=int(a.quantity)
        if a.is_equipment:return left
        for x in self.inventory.items:
            if x.item_id==a.item_id and not x.is_equipment and x.max_stack==a.max_stack:left=max(0,left-x.free_stack_space)
        return 0 if left<=0 else (left+a.max_stack-1)//a.max_stack

def award(self,a,all_or_nothing=True):
        need=self.required_new_slots(a)
        if all_or_nothing and need>self.inventory.free_slots:return InventoryAwardResult(0,a.quantity,0,0,'inventory_full')
        left=int(a.quantity); merged=0; ids=[]
        if not a.is_equipment:
            for x in self.inventory.items:
                if left<=0:break
                if x.item_id==a.item_id and not x.is_equipment and x.max_stack==a.max_stack:
                    n=min(left,x.free_stack_space);x.quantity+=n;left-=n;merged+=n
        while left>0 and self.inventory.free_slots>0:
            n=1 if a.is_equipment else min(left,a.max_stack)
            x=SimulationInventoryItem(self.inventory.allocate_id(),a.item_id,a.name,a.category,n,1 if a.is_equipment else a.max_stack,a.slot_key,a.item_level,a.rarity,armor_type=str(a.payload.get('armor_type','')),item_subtype=str(a.payload.get('item_subtype','')),weapon_hands=int(a.payload.get('weapon_hands',1)),sell_price=a.sell_price,stats=dict(a.payload.get('stats',{})))
            self.inventory.items.append(x);ids.append(x.simulation_item_id);left-=n
        self.inventory.validate();return InventoryAwardResult(a.quantity-left,left,len(ids),merged,'awarded' if left==0 else 'partial_capacity',ids)

def _equipment_award(self,mob:Dict[str,Any],payload:Dict[str,Any]):
        level=int(mob.get("level",1));rarity=str(payload.get("rarity","common"));slot=self.rng.choice(SLOTS);mult=RARITY_MULT[rarity]
        stats={};armor="";hands=1
        if slot=="main_hand":
            hands=2 if self.rng.random()<0.35 else 1;stats["weapon_min_damage"]=max(1,int(level*1.2*mult));stats["weapon_max_damage"]=max(2,int(level*2.0*mult));stats["str" if self.character_class in {"warrior","knight"} else "dex" if self.character_class in {"scout","rogue"} else "int"]=max(1,int(level*.7*mult))
        elif slot=="off_hand":stats["pdef" if self.character_class in {"warrior","knight","scout","rogue"} else "mdef"]=max(1,int(level*mult))
        else:
