def resolve_equipment_after_victory(self, gold: float):
        decisions = []
        sale_records = []
        before_ids = {item.simulation_item_id for item in self.inventory.items if item.is_equipment}
        equipped, rejected = self.equip_upgrades()
        protected = {value for value in self.equipment.slots.values() if value}
        sold_gold = 0.0
        for item in list(self.inventory.items):
            if not item.is_equipment or item.simulation_item_id in protected:
                continue
            sold_gold += float(item.sell_price) * item.quantity
            sale_records.append({
                "simulation_item_id": item.simulation_item_id,
                "item_id": item.item_id,
                "name": item.name,
                "category": item.category,
                "rarity": item.rarity,
                "quantity": item.quantity,
                "slot_key": item.slot_key,
                "item_level": item.item_level,
                "armor_type": item.armor_type,
                "stats": dict(item.stats),
                "destination": "sold_as_worse_equipment",
                "gold": round(float(item.sell_price) * item.quantity, 2),
            })
            self.inventory.items.remove(item)
        for slot_key, simulation_item_id in self.equipment.slots.items():
            if simulation_item_id and simulation_item_id in before_ids:
                item = next((row for row in self.inventory.items if row.simulation_item_id == simulation_item_id), None)
                if item is not None:
                    decisions.append({
                        "simulation_item_id": item.simulation_item_id,
                        "item_id": item.item_id,
                        "slot_key": slot_key,
                        "action": "equipped",
                    })
        self.inventory.validate()
        return round(gold + sold_gold, 2), {
            "equipped": equipped,
            "rejected": rejected,
            "decisions": decisions,
            "sale_records": sale_records,
            "sale_gold": round(sold_gold, 2),
        }

def city_maintenance(self,gold:float):
        equipped,rejected=self.equip_upgrades();protected={value for value in self.equipment.slots.values() if value}
        sold=[];received=0.0;quantity=0
        for item in list(self.inventory.items):
            if item.simulation_item_id in protected:continue
            if item.category=="equipment" or item.category=="trash":
                received+=float(item.sell_price)*item.quantity;quantity+=item.quantity;sold.append(item)
        for item in sold:self.inventory.items.remove(item)
        self.inventory.validate()
        records=[{"simulation_item_id": item.simulation_item_id, "item_id": item.item_id, "name": item.name, "category": item.category, "rarity": item.rarity, "quantity": item.quantity, "destination": "sold", "gold": round(float(item.sell_price)*item.quantity,2)} for item in sold]
        return round(gold+received,2),CityResult(len(sold),quantity,round(received,2),equipped,rejected,records)

def _consume(self,item_id,quantity):
  need=quantity
  for item in list(self.inventory.items):
   if item.item_id!=item_id:continue
   take=min(item.quantity,need);item.quantity-=take;need-=take
   if item.quantity<=0:self.inventory.items.remove(item)
   if need<=0:break
  return need==0

