def users_snapshot(db, include_volatile=False):
    all_columns = [row[1] for row in db.conn.execute("PRAGMA table_info(users)").fetchall()]
    columns = [
        name for name in all_columns
        if include_volatile or name not in VOLATILE_USER_COLUMNS
    ]
    select_list = ",".join(f'"{name}"' for name in columns)
    rows = [
        tuple(row)
        for row in db.conn.execute(
            f"SELECT {select_list} FROM users WHERE user_id>=0 ORDER BY user_id"
        ).fetchall()
    ]
    return columns, rows

def volatile_user_changes(before, after):
    before_columns, before_rows = before
    after_columns, after_rows = after
    if before_columns != after_columns:
        return ["volatile schema changed"]
    before_map = {row[before_columns.index("user_id")]: row for row in before_rows}
    after_map = {row[after_columns.index("user_id")]: row for row in after_rows}
    changes = []
    for user_id in sorted(set(before_map) | set(after_map)):
        if user_id not in before_map or user_id not in after_map:
            changes.append(f"user set changed for {user_id}")
            continue
        for index, column in enumerate(before_columns):
            if before_map[user_id][index] != after_map[user_id][index]:
                changes.append(f"user_id={user_id} column={column}")
    return changes

def negative_fixture_counts(db):
    result = {}
    tables = [
        row[0]
        for row in db.conn.execute(
            "SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%'"
        ).fetchall()
    ]
    for table in tables:
        try:
            columns = {
                row[1] for row in db.conn.execute(f'PRAGMA table_info("{table}")').fetchall()
            }
            if "user_id" not in columns:
                continue
            count = int(
                db.conn.execute(
                    f'SELECT COUNT(*) FROM "{table}" WHERE user_id<0'
                ).fetchone()[0]
                or 0
            )
            if count:
                result[table] = count
        except Exception:
            continue
    return result

def require_schema(connection: sqlite3.Connection) -> None:
    users_columns = {
        row[1] for row in connection.execute("PRAGMA table_info(users)").fetchall()
    }
    required_users = {"user_id", "character_name", "character_class", "last_activity_at"}
    if not required_users.issubset(users_columns):
        missing = sorted(required_users - users_columns)
        raise RuntimeError(f"users schema is missing columns: {missing}")

    reminder_columns = {
        row[1]
        for row in connection.execute("PRAGMA table_info(inactivity_reminders)").fetchall()
    }
    if not set(REMINDER_COLUMNS).issubset(reminder_columns):
        missing = sorted(set(REMINDER_COLUMNS) - reminder_columns)
        raise RuntimeError(f"inactivity_reminders schema is missing columns: {missing}")

def read_user(connection: sqlite3.Connection, user_id: int) -> sqlite3.Row:
    row = connection.execute(
        """
        SELECT user_id, character_name, character_class, last_activity_at
        FROM users
        WHERE user_id=?
        """,
        (user_id,),
    ).fetchone()
    if row is None:
        raise RuntimeError("Test user was not found in users")
    if not str(row["character_name"] or "").strip():
        raise RuntimeError("Test user has no character_name")
    if not str(row["character_class"] or "").strip():
        raise RuntimeError("Test user has no character_class")
    return row

def read_reminders(connection: sqlite3.Connection, user_id: int) -> list[dict]:
    rows = connection.execute(
        "SELECT * FROM inactivity_reminders WHERE user_id=? ORDER BY id",
        (user_id,),
    ).fetchall()
    return [{column: row[column] for column in REMINDER_COLUMNS} for row in rows]

