def verify(project_root: Path, contract: dict[str, Any]) -> dict[str, Any]:
    violations: list[dict[str, Any]] = []
    observations: list[dict[str, Any]] = []
    runtime_root = project_root / contract["runtime_root"]
    physical_runtime_exists = runtime_root.is_dir()

    declared_runtime = {Path(path).name for path in contract["runtime_packages"]}
    declared_support = set(contract["support_roots"])
    if declared_runtime != EXPECTED_RUNTIME_PACKAGES:
        violations.append({"rule": "RUNTIME_PACKAGE_SET", "expected": sorted(EXPECTED_RUNTIME_PACKAGES), "actual": sorted(declared_runtime)})
    if not EXPECTED_SUPPORT_ROOTS.issubset(declared_support):
        violations.append({"rule": "SUPPORT_ROOT_SET", "missing": sorted(EXPECTED_SUPPORT_ROOTS - declared_support)})

    duplicate_owners: dict[str, list[str]] = {}
    owners: dict[str, list[str]] = {}
    for path, metadata in contract["runtime_packages"].items():
        owners.setdefault(metadata["owner"], []).append(path)
        name = Path(path).name
        if not VALID_NAME.fullmatch(name):
            violations.append({"rule": "PACKAGE_NAMING", "path": path})
        if Path(path).name + ".py" in FORBIDDEN_CATCH_ALL:
            violations.append({"rule": "CATCH_ALL_PACKAGE_NAME", "path": path})
    duplicate_owners = {owner: paths for owner, paths in owners.items() if len(paths) > 1}
    if duplicate_owners:
        violations.append({"rule": "DUPLICATE_OWNER", "owners": duplicate_owners})

    files: list[Path] = []
    if physical_runtime_exists:
        files = sorted(runtime_root.rglob("*.py"))
        for path in files:
            relative = path.relative_to(project_root).as_posix()
            if path.name in FORBIDDEN_CATCH_ALL:
                violations.append({"rule": "FORBIDDEN_CATCH_ALL_MODULE", "file": relative})
            if path.name != "__init__.py" and not VALID_NAME.fullmatch(path.stem):
                violations.append({"rule": "MODULE_NAMING", "file": relative})
            try:
                ast.parse(path.read_text(encoding="utf-8", errors="replace"), filename=relative)
            except SyntaxError as exc:
                violations.append({"rule": "PYTHON_PARSE_ERROR", "file": relative, "error": str(exc)})
        physical_packages = {path.name for path in runtime_root.iterdir() if path.is_dir() and path.name != "__pycache__"}
        unknown = sorted(physical_packages - EXPECTED_RUNTIME_PACKAGES)
        missing = sorted(EXPECTED_RUNTIME_PACKAGES - physical_packages)
        if unknown:
            violations.append({"rule": "UNDECLARED_RUNTIME_PACKAGE", "packages": unknown})
        if missing:
            violations.append({"rule": "MISSING_RUNTIME_PACKAGE_AFTER_SCAFFOLD", "packages": missing})
    else:
        observations.append({"kind": "STAGE_BOUNDARY", "message": "Physical rom_v2 skeleton is intentionally reserved for Stage 21.3.1."})

    return {
        "schema_version": 1,
        "summary": {
            "status": "PASS" if not violations else "FAIL",
            "physical_runtime_exists": physical_runtime_exists,
            "physical_python_file_count": len(files),
            "declared_runtime_package_count": len(declared_runtime),
            "declared_support_root_count": len(declared_support),
            "violation_count": len(violations),
        },
        "declared_runtime_packages": sorted(declared_runtime),
        "declared_support_roots": sorted(declared_support),
        "observations": observations,
        "violations": violations,
    }

def _is_operation_boundary(node: ast.FunctionDef | ast.AsyncFunctionDef, file_path: str) -> bool:
    if OPERATION_HINT_RE.search(node.name):
        return True
    normalized = file_path.lower()
    return any(part in normalized for part in ("/commands/", "/handlers/", "/use_cases/", "/usecases/"))

def verify(root: Path, contract: dict[str, Any]) -> dict[str, Any]:
    violations: list[dict[str, Any]] = []
    status_rows = contract.get("statuses", [])
    keys = [row.get("key") for row in status_rows]
    if set(keys) != REQUIRED_STATUS_KEYS or len(keys) != len(set(keys)):
        violations.append({"rule": "STATUS_SET", "expected": sorted(REQUIRED_STATUS_KEYS), "actual": sorted(keys)})
    if contract.get("canonical_owner") != "rom_v2.application.result":
        violations.append({"rule": "CANONICAL_OWNER"})
    if not contract.get("mutation_contract", {}).get("unit_of_work_required"):
        violations.append({"rule": "UNIT_OF_WORK_REQUIRED"})
    if not contract.get("mutation_contract", {}).get("preconditions_before_first_mutation"):
        violations.append({"rule": "PRECONDITIONS_BEFORE_MUTATION"})
    if not contract.get("presentation_contract", {}).get("telegram_types_forbidden"):
        violations.append({"rule": "PRESENTATION_SEPARATION"})
    retryable = {row["key"] for row in status_rows if row.get("retryable")}
    if retryable != {"stale_state", "retryable_error"}:
        violations.append({"rule": "RETRYABILITY_SET", "actual": sorted(retryable)})
    mutating = {row["key"] for row in status_rows if row.get("mutation_allowed")}
    if mutating != {"success"}:
        violations.append({"rule": "MUTATION_ALLOWED_SET", "actual": sorted(mutating)})

    result_owners: list[dict[str, Any]] = []
    implicit_operation_results: list[dict[str, Any]] = []
    rom_v2 = root / "rom_v2"
    if rom_v2.is_dir():
        for path in sorted(rom_v2.rglob("*.py")):
            relative = path.relative_to(root).as_posix()
            try:
                tree = ast.parse(path.read_text(encoding="utf-8", errors="replace"), filename=relative)
            except SyntaxError as exc:
                violations.append({"rule": "PARSE_ERROR", "file": relative, "error": str(exc)})
                continue
            for node in ast.walk(tree):
                if isinstance(node, ast.ClassDef) and RESULT_CLASS_RE.fullmatch(node.name):
                    result_owners.append({"file": relative, "class": node.name, "line": node.lineno})
                if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)) and not node.name.startswith("_"):
                    annotation = _annotation_text(node.returns)
                    if _is_operation_boundary(node, relative) and not _is_result_annotation(annotation):
                        implicit_operation_results.append({"file": relative, "function": node.name, "line": node.lineno, "annotation": annotation or None})
    if len(result_owners) > 1:
        violations.append({"rule": "MULTIPLE_RESULT_OWNERS", "owners": result_owners})
    if result_owners and result_owners[0]["file"] != "rom_v2/application/result.py":
        violations.append({"rule": "WRONG_RESULT_OWNER", "owners": result_owners})
    if implicit_operation_results:
        violations.append({"rule": "IMPLICIT_OPERATION_RESULTS", "functions": implicit_operation_results})

    return {
        "schema_version": 2,
        "summary": {
            "status": "PASS" if not violations else "FAIL",
            "status_count": len(status_rows),
            "result_owner_count": len(result_owners),
            "implicit_public_result_count": len(implicit_operation_results),
            "violation_count": len(violations),
            "physical_result_model_exists": bool(result_owners),
        },
        "result_owners": result_owners,
        "implicit_public_results": implicit_operation_results,
        "violations": violations,
    }

def verify_contract() -> dict[str, Any]:
    """Return complete deterministic findings for the schema contract."""
    tables = dict(SCHEMA_CONTRACT["tables"])
    violations: list[dict[str, str]] = []
    if set(tables) != REQUIRED_TABLES:
        violations.append({"rule": "TABLE_SET", "detail": str(sorted(set(tables) ^ REQUIRED_TABLES))})
    for table_name, raw in sorted(tables.items()):
        table = dict(raw); columns = dict(table.get("columns", {})); primary_key = list(table.get("primary_key", []))
        if not table.get("owner"): violations.append({"rule": "MISSING_OWNER", "detail": table_name})
        if not primary_key or not set(primary_key).issubset(columns): violations.append({"rule": "PRIMARY_KEY", "detail": table_name})
        for column_name, raw_column in columns.items():
            spec = dict(raw_column)
            if spec.get("storage_type") not in ALLOWED_TYPES: violations.append({"rule": "COLUMN_TYPE", "detail": f"{table_name}.{column_name}"})
            if not isinstance(spec.get("nullable"), bool): violations.append({"rule": "NULLABILITY", "detail": f"{table_name}.{column_name}"})
            if not spec.get("generated_by"): violations.append({"rule": "GENERATION_OWNER", "detail": f"{table_name}.{column_name}"})
            if column_name in primary_key and spec.get("nullable"): violations.append({"rule": "NULLABLE_PRIMARY_KEY", "detail": f"{table_name}.{column_name}"})
        for unique in table.get("unique", []):
            if not unique or not set(unique).issubset(columns): violations.append({"rule": "UNIQUE_COLUMNS", "detail": f"{table_name}:{unique}"})
        for fk in table.get("foreign_keys", []):
            column_name=fk.get("column"); target=fk.get("target_table"); target_column=fk.get("target_column")
            if column_name not in columns or target not in tables or target_column not in dict(tables.get(target, {})).get("columns", {}): violations.append({"rule": "FOREIGN_KEY_TARGET", "detail": f"{table_name}:{fk}"})
            if fk.get("on_delete") not in ALLOWED_ACTIONS or fk.get("on_update") not in ALLOWED_ACTIONS: violations.append({"rule": "FOREIGN_KEY_ACTION", "detail": f"{table_name}:{fk}"})
    names: set[str] = set()
    for index in SCHEMA_CONTRACT["indexes"]:
        name=index.get("name"); table=index.get("table"); columns=index.get("columns", [])
        if not name or name in names: violations.append({"rule": "INDEX_NAME", "detail": str(name)})
        names.add(str(name))
        if table not in tables or not columns or not set(columns).issubset(dict(tables.get(table, {})).get("columns", {})): violations.append({"rule": "INDEX_COLUMNS", "detail": str(index)})
    deferred = dict(SCHEMA_CONTRACT.get("deferred_domains", {}))
    if set(deferred) != REQUIRED_DEFERRED: violations.append({"rule": "DEFERRED_DOMAIN_SET", "detail": str(sorted(set(deferred) ^ REQUIRED_DEFERRED))})
    for name, decision in deferred.items():
        if decision.get("decision") != "deferred_no_placeholder_table" or not decision.get("future_owner"): violations.append({"rule": "DEFERRED_DOMAIN_DECISION", "detail": name})
    if SCHEMA_CONTRACT.get("development_strategy") != "clean_reset_first": violations.append({"rule": "RESET_STRATEGY", "detail": "clean reset required"})
    if SCHEMA_CONTRACT.get("v1_data_strategy") != "do_not_migrate_test_data": violations.append({"rule": "V1_DATA_STRATEGY", "detail": "V1 test data must not migrate"})
    if SCHEMA_CONTRACT.get("money_policy") != "integer_minor_units": violations.append({"rule": "MONEY_POLICY", "detail": "integer minor units required"})
    if SCHEMA_CONTRACT.get("timestamp_policy") != "utc_iso8601_text": violations.append({"rule": "TIMESTAMP_POLICY", "detail": "UTC ISO-8601 required"})
    quest_checks = set(tables["quest_progress"].get("checks", []))
    required_quest_lifecycle = "(state_key = 'completed' AND completed_at_utc IS NOT NULL) OR (state_key <> 'completed' AND completed_at_utc IS NULL)"
    if required_quest_lifecycle not in quest_checks:
        violations.append({"rule": "QUEST_COMPLETION_BIDIRECTIONAL", "detail": "quest completion timestamp must exactly match completed state"})
    operation_checks = set(tables["operation_records"].get("checks", []))
    required_operation_lifecycle = "(status_key = 'completed' AND completed_at_utc IS NOT NULL) OR (status_key <> 'completed' AND completed_at_utc IS NULL)"
    if required_operation_lifecycle not in operation_checks:
        violations.append({"rule": "OPERATION_COMPLETION_BIDIRECTIONAL", "detail": "operation completion timestamp must exactly match completed status"})
    def has_fk(table_name: str, column_name: str, target_table: str, on_delete: str) -> bool:
        return any(
            fk.get("column") == column_name
            and fk.get("target_table") == target_table
            and fk.get("target_column") == "operation_id"
            and fk.get("on_delete") == on_delete
            and fk.get("on_update") == "CASCADE"
            for fk in tables[table_name].get("foreign_keys", [])
        )
    if not has_fk("crystal_ledger", "operation_id", "operation_records", "RESTRICT"):
        violations.append({"rule": "LEDGER_OPERATION_FK", "detail": "crystal ledger must retain exact-once operation evidence"})
    if not has_fk("item_reservations", "operation_id", "operation_records", "CASCADE"):
        violations.append({"rule": "RESERVATION_OPERATION_FK", "detail": "reservation lifetime must follow operation lifetime"})
    return {"status": "PASS" if not violations else "FAIL", "contract_revision": SCHEMA_CONTRACT["contract_revision"], "table_count": len(tables), "column_count": sum(len(dict(t["columns"])) for t in tables.values()), "index_count": len(SCHEMA_CONTRACT["indexes"]), "deferred_domain_count": len(deferred), "tables": tables, "indexes": list(SCHEMA_CONTRACT["indexes"]), "deferred_domains": deferred, "violations": violations}

