def consume_story_quest_item_quantity(
    connection, *, user_id: int, item_key: str, quantity: int
) -> int:
    """Consume an exact quantity across retained source rows, oldest first.

    The caller owns the surrounding transaction. Any insufficient or concurrent
    state raises before completion, allowing the outer transaction to roll back
    every row and the reward/status mutation together.
    """
    required = int(quantity)
    if required <= 0:
        raise StoryQuestPersistenceError("consume quantity must be positive")
    rows = connection.execute(
        """SELECT quest_id, quantity FROM user_story_quest_items
        WHERE user_id=? AND item_key=? AND quantity>0
        ORDER BY updated_at, quest_id""",
        (int(user_id), str(item_key)),
    ).fetchall()
    if sum(int(row[1] or 0) for row in rows) < required:
        raise StoryQuestConflictError("required quest item quantity is incomplete")
    remaining = required
    for quest_id, current_raw in rows:
        current = int(current_raw or 0)
        take = min(current, remaining)
        if take <= 0:
            continue
        if take == current:
            changed = connection.execute(
                """DELETE FROM user_story_quest_items
                WHERE user_id=? AND quest_id=? AND item_key=? AND quantity=?""",
                (int(user_id), str(quest_id), str(item_key), current),
            )
        else:
            changed = connection.execute(
                """UPDATE user_story_quest_items SET quantity=quantity-?, updated_at=?
                WHERE user_id=? AND quest_id=? AND item_key=? AND quantity=?""",
                (take, utc_now_iso(), int(user_id), str(quest_id), str(item_key), current),
            )
        if changed.rowcount != 1:
            raise StoryQuestConflictError("quest item quantity changed concurrently")
        remaining -= take
        if remaining == 0:
            break
    return required

def validate_event_drop_rules(rules: tuple, mob: dict) -> tuple[dict, ...]:
    if not isinstance(rules, tuple):
        raise EventRegistryError("event drop rules must be tuple")
    if not isinstance(mob, dict):
        raise EventRegistryError("event drop mob must be dict")
    if not mob.get("is_event"):
        return ()
    event_key = str(mob.get("event_key") or "").strip()
    mob_key = str(mob.get("event_mob_key") or "").strip()
    validated=[]; seen=set()
    for raw in rules:
        if not isinstance(raw, dict):
            raise EventRegistryError("event drop rule must be dict")
        rule=dict(raw); rule_id=str(rule.get("rule_id") or "").strip()
        if not rule_id or rule_id in seen:
            raise EventRegistryError("event drop rule_id must be unique and non-empty")
        if str(rule.get("event_key") or "").strip()!=event_key:
            continue
        target=str(rule.get("mob_key") or "*").strip()
        if target not in ("*",mob_key):
            continue
        item_id=int(rule.get("item_id")); quantity=int(rule.get("quantity",1)); chance=float(rule.get("chance_percent",0.0))
        if quantity <= 0:
            raise EventRegistryError("event drop quantity must be positive")
        if not 0.0 <= chance <= 100.0:
            raise EventRegistryError("event drop chance_percent must be between 0 and 100")
        from .item_namespace import validate_event_item_id
        validate_event_item_id(event_key,item_id)
        rule.update({"rule_id":rule_id,"event_key":event_key,"mob_key":target,"item_id":item_id,"quantity":quantity,"chance_percent":chance})
        seen.add(rule_id); validated.append(rule)
    return tuple(validated)

