            "inventory_id": int(inventory_id),

            "slot_key": str(slot_key),

            "name": f"{display_name} — {reason}",

            "reason": reason,

        })



    _equipment_write_sync_hp_v5(uid)

    return {

        "success": True,

        "removed_items": removed_items,

        "removed_count": len(removed_items),

    }

