 try:eligible=_stamp(datetime.fromisoformat(started.replace('Z','+00:00'))+timedelta(seconds=INACTIVITY_THRESHOLD_SECONDS))
 except Exception:return {'success':False,'claimed':False,'reason':'invalid_cycle'}
