def cancel_failed_accepted_pvp_duel_request(request_id: int, *, db_path=None) -> dict[str, Any]:
    """Convert an accepted request with no battle into cancelled, allowing a clean retry."""
    from systems import player_interaction_system as interaction
    connection = interaction._connect(db_path)
    try:
        connection.execute("BEGIN IMMEDIATE")
        row = connection.execute(
            "SELECT status,request_type FROM player_interaction_requests WHERE id=?",
            (int(request_id),),
        ).fetchone()
        if not row or row["request_type"] != "duel":
            connection.rollback(); return {"success": False, "reason": "request_not_found"}
        if row["status"] == "accepted":
            connection.execute(
                "UPDATE player_interaction_requests SET status='cancelled',revision=revision+1,updated_at=datetime('now'),responded_at=datetime('now') WHERE id=?",
                (int(request_id),),
            )
        connection.execute(
            "DELETE FROM player_activity_sessions WHERE reference_id=? AND activity_type IN ('duel_request','pvp_battle')",
            (int(request_id),),
        )
        connection.commit(); return {"success": True, "status": "cancelled"}
    except Exception:
        connection.rollback(); raise
    finally:
        connection.close()

def submit_pvp_action(
    battle_id: int,
    user_id: int,
    round_number: int,
    revision: int,
    action_type: str,
    skill_key: str | None = None,
    payload: Mapping[str, Any] | None = None,
    connection: sqlite3.Connection | None = None,
) -> dict[str, Any]:
    if action_type not in {"basic_attack", "skill", "afk_skip", "stunned_skip"}:
        raise ValueError("unsupported PvP action type")
    if action_type == "skill" and not skill_key:
        raise ValueError("skill_key is required for skill action")
    with _connection(connection) as conn:
        conn.execute("BEGIN IMMEDIATE")
        try:
            battle = conn.execute("SELECT * FROM pvp_battles WHERE id = ?", (int(battle_id),)).fetchone()
            if not battle or battle["status"] != "active":
                raise ValueError("PvP battle is not active")
            if int(battle["round_number"]) != int(round_number) or int(battle["revision"]) != int(revision):
                raise ValueError("stale PvP callback")
            participant = conn.execute(
                "SELECT 1 FROM pvp_participants WHERE battle_id = ? AND user_id = ?",
                (int(battle_id), int(user_id)),
            ).fetchone()
            if not participant:
                raise ValueError("actor does not belong to this PvP battle")
            conn.execute(
                """
                INSERT INTO pvp_round_actions(
                    battle_id, round_number, revision, user_id, action_type, skill_key, payload_json, submitted_at
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (int(battle_id), int(round_number), int(revision), int(user_id), action_type, skill_key, _json(dict(payload or {})), _iso()),
            )
            count = conn.execute(
                "SELECT COUNT(*) FROM pvp_round_actions WHERE battle_id = ? AND round_number = ? AND revision = ?",
                (int(battle_id), int(round_number), int(revision)),
            ).fetchone()[0]
            add_pvp_event(
                int(battle_id), "action_submitted", int(round_number), int(revision), int(user_id),
                payload={"action_type": action_type, "skill_key": skill_key}, connection=conn,
            )
            conn.commit()
            return {"accepted": True, "actions_ready": int(count), "both_ready": int(count) >= 2}
        except sqlite3.IntegrityError as exc:
            conn.rollback()
            raise ValueError("action already submitted for this round") from exc
        except Exception:
            conn.rollback()
            raise

def get_pvp_recovery_plan(
    now: datetime | None = None,
    connection: sqlite3.Connection | None = None,
) -> dict[str, Any]:
    moment = now or _utc_now()
    with _connection(connection) as conn:
        rows = conn.execute(
            "SELECT * FROM pvp_battles WHERE status IN ('waiting','active','resolving') ORDER BY id"
        ).fetchall()
        active = []
        expired = []
        resolving = []
        for row in rows:
            item = dict(row)
            deadline = _parse(item.get("action_deadline"))
            if item["status"] == "resolving":
                resolving.append(item["id"])
            elif deadline is not None and deadline <= moment:
                expired.append(item["id"])
            else:
                active.append(item["id"])
        return {"active": active, "expired": expired, "resolving": resolving}

def resolve_persisted_pvp_round(battle_id: int, round_number: int, revision: int, seed: int | None = None, connection: sqlite3.Connection | None = None) -> dict[str, Any]:
    """Resolve two persisted intents once and persist only duel-local participant state."""
    from dataclasses import asdict
    from systems.pvp_models import PvpActionIntent, PvpActorState
    from systems.pvp_round_engine import resolve_pvp_round
    with _connection(connection) as conn:
        if not claim_pvp_round_resolution(battle_id, round_number, revision, conn):
            return {"resolved": False, "reason": "resolution_not_claimed"}
        try:
            participants = get_pvp_participants(battle_id, conn)
            actions = get_pvp_round_actions(battle_id, round_number, revision, conn)
            if len(participants) != 2 or len(actions) != 2:
                conn.execute("UPDATE pvp_battles SET status='active', resolving=0 WHERE id=?", (int(battle_id),))
                conn.commit()
                return {"resolved": False, "reason": "actions_or_participants_incomplete"}
            actors = []
            for row in participants:
                snap = dict(row.get("snapshot") or {})
                snap.update({"user_id":row["user_id"],"class_key":row["class_key"],"max_hp":row["max_hp"],"hp":row["hp"],"max_mp":row["max_mp"],"mp":row["mp"],"resource_type":row["resource_type"],"resource":row["resource_value"],"combo":row["combo"],"cooldowns":row["cooldowns"],"effects":row["effects"],"consecutive_afk":row["consecutive_afk"],"stunned_next":bool(row["stunned_next"])})
                actors.append(PvpActorState.from_dict(snap))
            intents = {row["user_id"]: PvpActionIntent(row["user_id"], row["action_type"], row["skill_key"], row["payload"]) for row in actions}
            result = resolve_pvp_round(round_number, revision, actors[0], actors[1], intents[actors[0].user_id], intents[actors[1].user_id], seed=seed)
            for state in (result.actor_a, result.actor_b):
                conn.execute("""UPDATE pvp_participants SET hp=?,mp=?,resource_value=?,combo=?,consecutive_afk=?,stunned_next=?,cooldowns_json=?,effects_json=?,updated_at=? WHERE battle_id=? AND user_id=?""",(state["hp"],state["mp"],state["resource"],state["combo"],state["consecutive_afk"],1 if state["stunned_next"] else 0,_json(state["cooldowns"]),_json(state["effects"]),_iso(),int(battle_id),int(state["user_id"])))
            round_payload = {
                "round_number": result.round_number,
                "revision": result.revision,
                "terminal": result.terminal,
                "winner_id": result.winner_id,
                "reason": result.result_reason,
                "actors": [dict(result.actor_a), dict(result.actor_b)],
                "outcomes": [asdict(outcome) for outcome in result.outcomes],
                "events": list(result.events),
            }
            add_pvp_event(battle_id,"round_resolved",round_number,revision,payload=round_payload,connection=conn)
            if result.terminal:
                complete_pvp_battle(battle_id,result.result_reason or "terminal",result.winner_id,connection=conn)
            else:
                release_pvp_round_resolution(battle_id,revision,connection=conn)
            conn.commit()
            return {
                "resolved": True, "terminal": result.terminal,
                "winner_id": result.winner_id, "result_reason": result.result_reason,
                "round_payload": round_payload,
            }
        except Exception:
            conn.rollback()
            raise

def perform_refine_attempt(user_id, inventory_id, use_success_rune=False, idempotency_key=None, db_path=None):
    """Atomically consume resources, apply refine result, and persist one attempt."""
    import json
    import sqlite3
    from datetime import datetime, timezone
    from pathlib import Path
    uid = int(user_id)
    inv_id = int(inventory_id)
    use_rune = bool(use_success_rune)
    key = str(idempotency_key or "").strip()
    if not key:
        return {"success": False, "message": "❌ Відсутній ключ операції заточки."}
    path = Path(db_path) if db_path is not None else Path(__file__).resolve().parents[1] / "game.db"
    conn = sqlite3.connect(str(path), timeout=30)
    conn.row_factory = sqlite3.Row
    conn.execute("PRAGMA foreign_keys=ON")
    conn.execute("PRAGMA busy_timeout=30000")
    try:
        conn.executescript("""CREATE TABLE IF NOT EXISTS refine_attempts(
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id INTEGER NOT NULL,
            inventory_id INTEGER NOT NULL,
            item_id INTEGER NOT NULL,
            refine_kind TEXT NOT NULL,
            old_level INTEGER NOT NULL,
            new_level INTEGER NOT NULL,
            success_chance INTEGER NOT NULL,
            roll INTEGER,
            refine_success INTEGER NOT NULL,
            used_success_rune INTEGER NOT NULL,
            stone_quantity INTEGER NOT NULL DEFAULT 1,
            success_rune_quantity INTEGER NOT NULL DEFAULT 0,
            idempotency_key TEXT NOT NULL UNIQUE,
            created_at TEXT NOT NULL,
            FOREIGN KEY(user_id) REFERENCES users(user_id) ON DELETE RESTRICT,
            FOREIGN KEY(item_id) REFERENCES items(id) ON DELETE RESTRICT
        );CREATE INDEX IF NOT EXISTS ix_refine_attempts_user ON refine_attempts(user_id,id DESC);""")
        conn.commit()
        conn.execute("BEGIN IMMEDIATE")
        old_attempt = conn.execute("SELECT * FROM refine_attempts WHERE idempotency_key=?", (key,)).fetchone()
        if old_attempt:
            conn.commit()
            row = dict(old_attempt)
            return {"success": True, "idempotent_replay": True, "refine_success": bool(row["refine_success"]), "refine_kind": row["refine_kind"], "old_level": row["old_level"], "new_level": row["new_level"], "chance": row["success_chance"], "roll": row["roll"], "used_success_rune": bool(row["used_success_rune"]), "message": "ℹ️ Цю спробу заточки вже виконано."}
        item = conn.execute("""SELECT inventory.id,inventory.user_id,inventory.item_id,COALESCE(inventory.refine_level,0) refine_level,items.name,items.type,items.category,items.slot_key,items.weapon_hands,items.item_subtype,items.armor_type FROM inventory JOIN items ON items.id=inventory.item_id WHERE inventory.id=?""", (inv_id,)).fetchone()
        if not item:
            conn.rollback(); return {"success": False, "message": "❌ Предмет не знайдено."}
        if int(item["user_id"]) != uid:
            conn.rollback(); return {"success": False, "message": "❌ Це не твій предмет."}
        info = dict(item)
        check = can_refine_item(info)
        if not check.get("success"):
            conn.rollback(); return check
        def total(item_id):
            return int(conn.execute("SELECT COALESCE(SUM(quantity),0) FROM inventory WHERE user_id=? AND item_id=? AND quantity>0", (uid,item_id)).fetchone()[0])
        if total(REFINE_STONE_ITEM_ID) < 1:
            conn.rollback(); return {"success": False, "message": "❌ Потрібен 🪨 Камінь Посилення."}
        if use_rune and total(SUCCESS_RUNE_ITEM_ID) < 1:
            conn.rollback(); return {"success": False, "message": "❌ Потрібна 💎 Руна Успіху."}
        def consume(item_id):
            row = conn.execute("SELECT id,quantity FROM inventory WHERE user_id=? AND item_id=? AND quantity>0 ORDER BY id LIMIT 1", (uid,item_id)).fetchone()
            if not row: raise RuntimeError("resource disappeared during refine")
            if int(row["quantity"]) == 1: conn.execute("DELETE FROM inventory WHERE id=? AND user_id=?", (int(row["id"]),uid))
            else: conn.execute("UPDATE inventory SET quantity=quantity-1 WHERE id=? AND user_id=? AND quantity>1", (int(row["id"]),uid))
            from db_modules.inventory import compact_user_item_stacks
            compact_user_item_stacks(uid, item_id, commit=False, connection=conn)
        kind = check["refine_kind"]
        current = int(check["current_level"])
        roll_result = roll_refine_success(kind,current,use_rune)
        new_level = current + 1 if roll_result["success"] else get_refine_failure_level(kind,current)
        consume(REFINE_STONE_ITEM_ID)
        if use_rune: consume(SUCCESS_RUNE_ITEM_ID)
        changed = conn.execute("UPDATE inventory SET refine_level=? WHERE id=? AND user_id=? AND COALESCE(refine_level,0)=?", (new_level,inv_id,uid,current)).rowcount
        if changed != 1: raise RuntimeError("refine target changed concurrently")
        now = datetime.now(timezone.utc).isoformat()
        conn.execute("INSERT INTO refine_attempts(user_id,inventory_id,item_id,refine_kind,old_level,new_level,success_chance,roll,refine_success,used_success_rune,stone_quantity,success_rune_quantity,idempotency_key,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)", (uid,inv_id,int(item["item_id"]),kind,current,new_level,int(roll_result["chance"]),roll_result["roll"],1 if roll_result["success"] else 0,1 if use_rune else 0,1,1 if use_rune else 0,key,now))
        max_level = WEAPON_MAX_REFINE_LEVEL if kind == "weapon" else ARMOR_MAX_REFINE_LEVEL
        if bool(roll_result["success"]) and current == max_level - 1 and new_level == max_level:
            from systems.world_chronicle_system import (
                get_character_name_snapshot,
                record_world_chronicle_event,
            )
            character_name = get_character_name_snapshot(uid, connection=conn)
            if character_name:
                record_world_chronicle_event(
                    "equipment_max_refine",
                    uid,
                    character_name,
                    f"equipment_max_refine:{inv_id}:{max_level}",
                    subject_key=str(item["item_id"]),
                    subject_name_snapshot=str(item["name"]),
                    metadata={"level": max_level},
                    connection=conn,
                )
        conn.commit()
        if roll_result["success"]: message=f"✅ Заточка успішна: +{current} → +{new_level}"
        elif new_level < current: message=f"❌ Заточка не вдалася: +{current} → +{new_level}"
        else: message=f"❌ Заточка не вдалася: +{current} без змін"
        return {"success": True, "idempotent_replay": False, "refine_success": bool(roll_result["success"]), "refine_kind": kind, "old_level": current, "new_level": new_level, "chance": int(roll_result["chance"]), "roll": roll_result["roll"], "used_success_rune": use_rune, "message": message}
    except Exception as error:
        try: conn.rollback()
        except Exception: pass
        return {"success": False, "message": f"❌ Заточку скасовано без списання ресурсів: {error}"}
    finally:
        conn.close()

